import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

test('adr-create documents the live AgentDB key/value/tier and causal-edge schema', () => {
  const skill = readFileSync(
    new URL('../../skills/adr-create/SKILL.md', import.meta.url),
    'utf8',
  );
  assert.doesNotMatch(skill, /^\s*-\s+path:/m);
  assert.match(skill, /^\s*-\s+key:\s+`mem:ADR-NNN`/m);
  assert.match(skill, /^\s*-\s+tier:\s+`semantic`/m);
  assert.match(skill, /value: a JSON-encoded string:/);
  assert.match(skill, /^\s*-\s+sourceId:\s+`mem:ADR-NNN`/m);
  assert.match(skill, /^\s*-\s+targetId:\s+`mem:ADR-RELATED`/m);

  for (const relative of [
    '../../REFERENCE.md',
    '../../commands/adr.md',
  ]) {
    const companion = readFileSync(new URL(relative, import.meta.url), 'utf8');
    assert.doesNotMatch(companion, /(?:--path|\bat path)[^\n]*adr\/ADR-/i);
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';

import {
  adrRecordKey,
  adrRecordValue,
  edgeKey,
  memoryStoreArgs,
  parseEdgeKey,
  uniqueEdges,
} from '../lib/index-records.mjs';

test('stable ADR keys are explicitly upserted when mutable metadata changes', () => {
  const proposed = {
    id: 'ADR-007',
    file: 'docs/adr/ADR-007-bullet-contract.md',
    title: 'Bullet contract',
    context: 'Context',
    status: 'proposed',
    date: '2026-07-29',
    tags: ['agentdb'],
  };
  const accepted = { ...proposed, status: 'accepted', tags: ['agentdb', 'accepted'] };

  assert.equal(adrRecordKey(proposed), adrRecordKey(accepted));
  assert.notEqual(adrRecordValue(proposed), adrRecordValue(accepted));

  const args = memoryStoreArgs('adr-patterns', adrRecordKey(accepted), adrRecordValue(accepted));
  assert.equal(args.filter((arg) => arg === '--upsert').length, 1);
  assert.ok(args.includes('--key=ADR-007::ADR-007-bullet-contract'));
  assert.ok(args.some((arg) => arg.includes('status: accepted')));
});

test('edge identity is deterministic and duplicate semantic triples collapse', () => {
  const edge = { relation: 'depends-on', from: 'ADR-007', to: 'ADR-003' };
  assert.equal(edgeKey(edge), 'depends-on:ADR-007->ADR-003');
  assert.equal(edgeKey({ ...edge }), edgeKey(edge));

  const unique = uniqueEdges([
    edge,
    { ...edge },
    { relation: 'related', from: 'ADR-007', to: 'ADR-003' },
  ]);
  assert.deepEqual(unique.map(edgeKey), [
    'depends-on:ADR-007->ADR-003',
    'related:ADR-007->ADR-003',
  ]);

  const args = memoryStoreArgs('adr-edges', edgeKey(edge), edge);
  assert.ok(args.includes('--upsert'));
  assert.ok(args.includes('--key=depends-on:ADR-007->ADR-003'));

  assert.deepEqual(parseEdgeKey('depends-on:ADR-007->ADR-003'), {
    relation: 'depends-on',
    from: 'ADR-007',
    to: 'ADR-003',
    key: 'depends-on:ADR-007->ADR-003',
  });
  assert.deepEqual(parseEdgeKey('depends-on:ADR-007->ADR-003:1721061000000-a1b2c3'), {
    relation: 'depends-on',
    from: 'ADR-007',
    to: 'ADR-003',
    key: 'depends-on:ADR-007->ADR-003:1721061000000-a1b2c3',
  });
});

import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';

import { parseAdr } from '../lib/parse-adrs.mjs';

test('adr-create bullet metadata and relationship lines round-trip through adr-index', () => {
  const root = mkdtempSync(join(tmpdir(), 'ruflo-adr-contract-'));
  try {
    const adrDir = join(root, 'docs', 'adr');
    mkdirSync(adrDir, { recursive: true });
    const file = join(adrDir, 'ADR-007-bullet-contract.md');
    writeFileSync(file, `# ADR-007: Bullet contract

- **Status**: accepted
- **Date**: 2026-07-29
- **Tags**: agentdb, lifecycle, graph
- **Supersedes**: ADR-006
- **Amends**: ADR-005
- **Related**: ADR-004
- **Depends-on**: ADR-003

## Context

The adr-create template and adr-index parser must agree.
`);

    const parsed = parseAdr(file, root);
    assert.equal(parsed.status, 'accepted');
    assert.equal(parsed.date, '2026-07-29');
    assert.deepEqual(parsed.tags, ['agentdb', 'lifecycle', 'graph']);
    assert.deepEqual(
      new Set(parsed.links.map(({ from, to, relation }) => `${relation}:${from}->${to}`)),
      new Set([
        'supersedes:ADR-006->ADR-007',
        'amends:ADR-007->ADR-005',
        'related:ADR-007->ADR-004',
        'depends-on:ADR-007->ADR-003',
      ]),
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { SKIP_DIRS, findAdrs } from '../lib/parse-adrs.mjs';

// #2911: ruvnet-brain clones ~50 external repos under `.brain/repo/clones/`,
// many with their own docs/adr/. Without `.brain` in SKIP_DIRS, findAdrs()
// walks into those clones and returns hundreds of foreign ADRs alongside
// the project's own — and since `.brain` sorts before `docs`, the
// project's ADRs land at the end of the walk, dead last.

test('SKIP_DIRS includes .brain', () => {
  assert.ok(SKIP_DIRS.has('.brain'));
});

test('findAdrs does not descend into .brain', () => {
  const root = mkdtempSync(join(tmpdir(), 'ruflo-adr-2911-'));
  try {
    // Project's own ADR
    mkdirSync(join(root, 'docs', 'adr'), { recursive: true });
    writeFileSync(join(root, 'docs', 'adr', 'ADR-001-real.md'), '# ADR-001\n');

    // A foreign clone under .brain with its own docs/adr/
    mkdirSync(join(root, '.brain', 'repo', 'clones', 'some-external-repo', 'docs', 'adr'), {
      recursive: true,
    });
    writeFileSync(
      join(root, '.brain', 'repo', 'clones', 'some-external-repo', 'docs', 'adr', 'ADR-999-foreign.md'),
      '# ADR-999\n',
    );

    const found = findAdrs(root);
    const names = found.map((p) => p.split('/').pop());

    assert.deepEqual(names, ['ADR-001-real.md']);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

#!/usr/bin/env node
// One-shot ADR importer for the ruflo-adr plugin.
//
// Walks the working directory (or ADR_ROOT override), parses every ADR file
// under */docs/adr/ or */docs/adrs/, persists records to the `adr-patterns`
// namespace, persists causal edges to the `adr-edges` namespace, prints a
// summary with status counts + relationship breakdown + dangling-ref check.
//
// Handles two ADR formats:
//   1. v3-style:  `# ADR-097: Title` heading + `**Status**: Proposed` line
//   2. plugin-style: YAML frontmatter (`status: Proposed`) at file head
//
// Usage:
//   node scripts/import.mjs                         # markdown summary to stdout
//   IMPORT_FORMAT=json node scripts/import.mjs       # JSON summary
//   IMPORT_DRY_RUN=1 node scripts/import.mjs         # parse + summarize, skip memory_store
//   ADR_ROOT=/path/to/repo node scripts/import.mjs   # override scan root (default: cwd)
//
// Why a script, not raw MCP calls: 70+ ADRs × multiple memory_store calls each
// is hundreds of MCP round-trips. spawnSync over the CLI is materially faster
// and avoids shell-quoting pitfalls in the ADR titles.

import { spawnSync } from 'node:child_process';
import { findAdrs, parseAdr } from './lib/parse-adrs.mjs';
import {
  adrRecordKey,
  adrRecordValue,
  edgeKey,
  edgeValue,
  memoryStoreArgs,
  uniqueEdges,
} from './lib/index-records.mjs';

// #2781 (Jordi-Izquierdo-DDS): CLI_CORE=1 previously routed writes through
// `@claude-flow/cli-core@alpha`, whose JsonMemoryBackend lives in a different
// store than `@claude-flow/cli@latest`'s SQLite backend. The default
// `ruflo memory search` reader hits the SQLite store, so setting CLI_CORE=1
// for the ~2s cold-cache speedup silently made `import` succeed against a
// store the default reader never looks at ("147/147 stored" but zero hits
// in later searches). Unified on the default CLI so writer and reader
// always agree — the CLI_CORE env var is now honored as read-only/logged
// but no longer routes to a different package.
if (process.env.CLI_CORE === '1') {
  console.warn(
    '[ruflo-adr] warning: CLI_CORE=1 is ignored — writing to the default ' +
    "`@claude-flow/cli@latest` store so `ruflo memory search` can find the records (#2781).",
  );
}

const ROOT = process.env.ADR_ROOT || process.cwd();

function memoryStore(namespace, key, value) {
  // #2474 Bug 1 (fatal): ADR titles like "ADR-005 — Repository …" contain
  // a U+2014 em-dash. \`npm exec\` runs argv validation BEFORE handing args
  // to the underlying bin, and \`commander\`-style argv with a non-ASCII
  // dash that starts an arg makes it reject with:
  //   npm error arg Argument starts with non-ascii dash, this is probably invalid: — …
  // Result: every store failed → \`Records stored: 0/N\`.
  //
  // Use the \`--flag=value\` form so npm sees a single \`--value=…\` token
  // and doesn't try to interpret the leading character of the value.
  // This works on both legacy and current npm; the underlying CLI accepts
  // \`--flag=value\` and \`--flag value\` equivalently.
  // #2666 point 2: without `cwd: ROOT`, this subprocess inherits THIS
  // process's own cwd, so `ADR_ROOT=/other/repo node import.mjs` run from
  // anywhere else scans the right files but writes to the wrong
  // `.swarm/memory.db` (the CLI resolves the db path relative to the
  // subprocess's cwd, not ADR_ROOT). Every memory subprocess call in this
  // plugin must pass `cwd: ROOT` so the scan root and the db root agree.
  // #2660: pass --upsert explicitly. The importer owns stable logical keys,
  // so re-running it must refresh changed ADRs and relationships in place.
  // Do not depend on a CLI parser default for this data-integrity contract.
  const r = spawnSync('npx', memoryStoreArgs(namespace, key, value),
    { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', cwd: ROOT });
  if (r.status !== 0) {
    return 'error: ' + (r.stderr || r.stdout || '').slice(0, 100);
  }
  return 'ok';
}

const dryRun = process.env.IMPORT_DRY_RUN === '1';
const fmt = process.env.IMPORT_FORMAT || 'markdown';

const files = findAdrs(ROOT);
const adrs = files.map((f) => parseAdr(f, ROOT));
const byId = new Map();
const parsedEdges = [];
for (const a of adrs) {
  byId.set(a.id, a);
  parsedEdges.push(...a.links);
}
const allEdges = uniqueEdges(parsedEdges);

let storedRecords = 0, storedEdges = 0;
const errors = [];
if (!dryRun) {
  for (const a of adrs) {
    const r = memoryStore('adr-patterns', adrRecordKey(a), adrRecordValue(a));
    if (r === 'ok') storedRecords++;
    else errors.push(`${a.id} ${a.file}: ${r}`);
  }
  for (const e of allEdges) {
    const r = memoryStore('adr-edges', edgeKey(e), edgeValue(e));
    if (r === 'ok') storedEdges++;
    else errors.push(`${edgeKey(e)}: ${r}`);
  }
}

const danglingRefs = allEdges.filter((e) => !byId.has(e.to));
const supersededIds = new Set(allEdges.filter((x) => x.relation === 'supersedes').map((x) => x.from));
const statusMismatches = [];
for (const id of supersededIds) {
  const a = byId.get(id);
  if (a && !/superseded/i.test(a.status)) statusMismatches.push({ id, status: a.status, file: a.file });
}

const byStatus = {};
for (const a of adrs) {
  const k = (a.status || 'unknown').toLowerCase();
  byStatus[k] = (byStatus[k] || 0) + 1;
}
const byRelation = {};
for (const e of allEdges) byRelation[e.relation] = (byRelation[e.relation] || 0) + 1;
const bySource = {};
for (const a of adrs) {
  const src = a.file.split('/docs/')[0];
  bySource[src] = (bySource[src] || 0) + 1;
}

const result = {
  scannedRoot: ROOT,
  total: adrs.length,
  sourceDirs: Object.keys(bySource).length,
  storedRecords, storedEdges, dryRun,
  byStatus, byRelation, bySource,
  edges: allEdges.length,
  danglingRefs, statusMismatches, errors,
};

if (fmt === 'json') {
  console.log(JSON.stringify(result, null, 2));
  process.exit(0);
}

console.log('## ADR Index Summary');
console.log('');
console.log(`Total ADRs: **${result.total}** across ${result.sourceDirs} source dirs (root: ${ROOT})`);
console.log(`Records stored to \`adr-patterns\`: ${result.storedRecords}/${result.total}${dryRun ? ' (dry-run, skipped)' : ''}`);
console.log(`Edges stored to \`adr-edges\`: ${result.storedEdges}/${result.edges}${dryRun ? ' (dry-run, skipped)' : ''}`);
console.log('');
console.log('### By status');
for (const [k, n] of Object.entries(byStatus).sort((a, b) => b[1] - a[1])) console.log(`- ${k}: ${n}`);
console.log('');
console.log(`### Relationships: **${result.edges}** edges`);
for (const [k, n] of Object.entries(byRelation).sort((a, b) => b[1] - a[1])) console.log(`- ${k}: ${n}`);
console.log('');
console.log('### Issues found');
console.log(`- Dangling refs (edge → non-existent ADR): ${danglingRefs.length}`);
for (const d of danglingRefs.slice(0, 10)) console.log(`  - ${d.relation} ${d.from} → ${d.to} (missing)`);
console.log(`- Status mismatches (superseded but not marked): ${statusMismatches.length}`);
for (const m of statusMismatches.slice(0, 10)) console.log(`  - ${m.id} status='${m.status}' (${m.file})`);
console.log(`- Storage errors: ${errors.length}`);
for (const e of errors.slice(0, 5)) console.log(`  - ${e}`);
console.log('');
console.log('### Source breakdown');
for (const [s, n] of Object.entries(bySource).sort((a, b) => b[1] - a[1]).slice(0, 12)) console.log(`- ${s}: ${n}`);

// Pure record construction helpers shared by adr-index and adr-reindex.
//
// Keeping identity and CLI argv construction here makes the persistence
// contract directly testable without spawning `npx` or touching memory.db.

import { basename } from 'node:path';

export const CLI_PKG = '@claude-flow/cli@latest';

export function adrRecordKey(adr) {
  return `${adr.id}::${basename(adr.file, '.md')}`;
}

export function adrRecordValue(adr) {
  return `${adr.title} — ${adr.context || '(no context)'}\n\n` +
    `file: ${adr.file}\n` +
    `status: ${adr.status}\n` +
    `date: ${adr.date}\n` +
    `tags: ${adr.tags.join(',')}`;
}

// An ADR relationship's identity is its semantic triple. Timestamps describe
// an observation; they must not be part of identity or every index run creates
// another logically-identical edge (#2660).
export function edgeKey(edge) {
  return `${edge.relation}:${edge.from}->${edge.to}`;
}

// Accept the deterministic #2660 key and the legacy timestamp-random suffix
// so existing installations remain verifiable after upgrading.
export function parseEdgeKey(key) {
  const match = /^([\w-]+):([^:]+)->([^:]+?)(?::\d+-[a-z0-9]+)?$/i.exec(key);
  if (!match) return null;
  return { relation: match[1], from: match[2], to: match[3], key };
}

export function edgeValue(edge, capturedAt = new Date().toISOString()) {
  return JSON.stringify({ ...edge, capturedAt });
}

export function uniqueEdges(edges) {
  const byIdentity = new Map();
  for (const edge of edges) {
    const key = edgeKey(edge);
    if (!byIdentity.has(key)) byIdentity.set(key, edge);
  }
  return [...byIdentity.values()];
}

export function memoryStoreArgs(namespace, key, value) {
  const valueStr = typeof value === 'string' ? value : JSON.stringify(value);
  return [
    CLI_PKG, 'memory', 'store',
    `--namespace=${namespace}`,
    `--key=${key}`,
    '--upsert',
    `--value=${valueStr}`,
  ];
}

// Shared ADR file-scan + parse logic for the ruflo-adr plugin scripts
// (import.mjs, reindex.mjs). Extracted from import.mjs (#2666) so a
// full reconcile (reindex.mjs) doesn't duplicate ~150 lines of dual-format
// (v3-style / plugin-style frontmatter) parsing and drift out of sync with it.
//
// Pure functions only — no memory_store / subprocess calls live here. Callers
// own persistence.

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, basename } from 'node:path';

// #2474 bonus: `.claude/worktrees/*` mirrors the repo so every ADR was
// indexed 2-3x. Skip the whole `.claude` tree — it's all ruflo runtime
// state (worktrees, scheduled tasks, etc.), never authored content.
//
// #2911: `.brain` is ruvnet-brain's own tree, holding shallow clones of
// ~50 external repos under `.brain/repo/clones/` — many carrying their
// own `docs/adr/`. Left unskipped, a walk from the project root picks up
// every foreign ADR (measured: 1,415 foreign vs 19 belonging to the
// project) and, because `.brain` sorts before `docs`, the project's own
// ADRs land dead last in the walk order — an interrupted run can index
// hundreds of foreign ADRs and zero of the project's.
export const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'v2', '.next', '.turbo', 'build', '.claude', '.brain']);

// #2474 Bug 4: parseId padded ADR numbers, but extractAdrRefs's
// padStart-then-strip pipeline produced different results for the same
// numeric value. A repo mixing `0001-foo.md` (parseId → ADR-0001) with
// a body line `Supersedes: ADR-0001` (extractAdrRefs → ADR-001) drops
// every edge as dangling. Single normalizer keeps both paths in lockstep.
export function normalizeAdrId(raw) {
  const digits = String(raw).replace(/^ADR-?/i, '').trim();
  if (!/^\d+$/.test(digits)) return `ADR-${raw}`;
  // Canonical form: ≤3 digits → zero-pad to 3 (legacy default);
  // ≥4 digits → keep as-is. Either way, the same numeric input from
  // a filename and from a body reference now produce the same key.
  return digits.length >= 4 ? `ADR-${digits}` : `ADR-${digits.padStart(3, '0')}`;
}

export function findAdrs(dir, out = []) {
  let entries;
  try { entries = readdirSync(dir); } catch { return out; }
  for (const e of entries) {
    if (SKIP_DIRS.has(e)) continue;
    const p = join(dir, e);
    let st;
    try { st = statSync(p); } catch { continue; }
    if (st.isDirectory()) {
      findAdrs(p, out);
    } else if (e.endsWith('.md') && (p.includes('/docs/adr/') || p.includes('/docs/adrs/'))) {
      out.push(p);
    }
  }
  return out;
}

export function parseAdr(path, root) {
  const text = readFileSync(path, 'utf-8');
  const id = parseId(path, text);
  const title = parseTitle(text);
  const status = parseStatus(text);
  const date = parseDate(text);
  const tags = parseTags(text);
  const context = parseContextFirstParagraph(text);
  const links = parseLinks(text, id);
  return { id, title, status, date, tags, context, links, file: path.replace(root + '/', '') };
}

function parseId(path, text) {
  const fm = /^---\s*$([\s\S]*?)^---\s*$/m.exec(text);
  if (fm) {
    const m = /^id:\s*(\S+)/m.exec(fm[1]);
    if (m) return normalizeAdrId(m[1]);
  }
  const fname = basename(path, '.md');
  const m = /^(ADR-?\d+|\d{3,4})/i.exec(fname);
  if (m) return normalizeAdrId(m[1]);
  return fname;
}

function parseTitle(text) {
  const fm = /^---\s*$([\s\S]*?)^---\s*$/m.exec(text);
  if (fm) {
    const m = /^title:\s*(.+)$/m.exec(fm[1]);
    if (m) return m[1].trim();
  }
  const m = /^#\s*(?:ADR-?\d+:?\s*)?(.+?)$/m.exec(text);
  return m ? m[1].trim() : '(untitled)';
}

function parseStatus(text) {
  const fm = /^---\s*$([\s\S]*?)^---\s*$/m.exec(text);
  if (fm) {
    const m = /^status:\s*(.+)$/im.exec(fm[1]);
    if (m) return m[1].trim();
  }
  // #2474 Bug 2: also accept `**Status:**` (colon inside the bold span),
  // the widely-used Nygard / MADR style. Previous regex only matched
  // `**Status**:` (colon outside) and dropped every Nygard-style ADR
  // to status=Unknown. Now the colon can sit on either side of the `**`.
  // Strip parenthetical qualifiers like "Proposed (v3.6.x)" -> "Proposed".
  //
  // #2781 (Jordi-Izquierdo-DDS): tolerate an optional Markdown list-item
  // prefix (`- **Status**: proposed`) — that's exactly what adr-create's
  // own template emits, and the column-0-anchored regex dropped every
  // freshly-scaffolded ADR to status=Unknown, making adr-review a no-op.
  let m = /^[-*+]?\s*\*\*Status:?\*\*:?\s*([A-Za-z][A-Za-z\- ]*?)(?:\s*\(.*?\))?\s*$/m.exec(text);
  if (m) return m[1].trim();
  // Also handle full-bold MADR style: **Status: Value** (entire phrase bolded)
  m = /^[-*+]?\s*\*\*Status:\s*([A-Za-z][A-Za-z\- ]*?)(?:\s*\([^)]*\))?\*\*\s*$/m.exec(text);
  return m ? m[1].trim() : 'Unknown';
}

function parseDate(text) {
  const fm = /^---\s*$([\s\S]*?)^---\s*$/m.exec(text);
  if (fm) {
    const m = /^date:\s*(\S+)/m.exec(fm[1]);
    if (m) return m[1];
  }
  // #2659: adr-create emits metadata as Markdown list items. Accept the
  // optional list marker and both common colon placements, matching Status.
  const m = /^[-*+]?\s*\*\*Date:?\*\*:?\s*(\S+)/m.exec(text);
  return m ? m[1] : '';
}

function parseTags(text) {
  const fm = /^---\s*$([\s\S]*?)^---\s*$/m.exec(text);
  if (fm) {
    const m = /^tags:\s*\[([^\]]+)\]/m.exec(fm[1]);
    if (m) return m[1].split(',').map((s) => s.trim()).filter(Boolean);
  }
  const m = /^[-*+]?\s*\*\*Tags:?\*\*:?\s*(.+)$/m.exec(text);
  return m ? m[1].split(',').map((s) => s.trim()).filter(Boolean) : [];
}

function parseContextFirstParagraph(text) {
  const m = /^##\s*Context\s*$\s*([\s\S]+?)(?=^##\s|\Z)/m.exec(text);
  if (!m) return '';
  return m[1].trim().split(/\n\s*\n/)[0].replace(/\s+/g, ' ').slice(0, 400);
}

// Extract ADR-NNN references from a link line. CRITICAL: must distinguish ADR
// references from GitHub issue numbers (#1697 etc.) which the prior version
// false-positively captured as "ADR-1697". We only recognize bare numbers as
// ADR refs when they appear in a known ADR-link section AND they don't look
// like GitHub issues (no leading #, no leading "issue").
function parseLinks(text, selfId) {
  const out = [];
  // Frontmatter relationships
  const fm = /^---\s*$([\s\S]*?)^---\s*$/m.exec(text);
  if (fm) {
    for (const [field, relation] of [
      ['supersedes', 'supersedes'],
      ['amended-by', 'amends'],
      ['amends', 'amends'],
      ['related', 'related'],
      ['depends-on', 'depends-on'],
    ]) {
      const re = new RegExp(`^${field}:\\s*\\[?([^\\]\\n]+)\\]?$`, 'mi');
      const m = re.exec(fm[1]);
      if (m) for (const ref of extractAdrRefs(m[1])) {
        if (relation === 'supersedes') out.push({ from: ref, to: selfId, relation });
        else out.push({ from: selfId, to: ref, relation });
      }
    }
  }
  // Body relationship lines. #2474 Bug 3: loosened to accept both colon
  // placements (`**Supersedes:**` and `**Supersedes**:`) and an optional
  // parenthetical qualifier like `**Supersedes (partial):**` — same
  // tolerance as parseStatus.
  //
  // #2781 (Jordi-Izquierdo-DDS): a wrapped relation like
  //   **Related**: ADR-124,
  //   ADR-125
  // silently dropped ADR-125 because `(.+)$` under /m only captures one
  // physical line. Now capture the first line plus any continuation lines
  // that don't look like the start of a new field (bold **Label**:), a
  // heading (`##`), a horizontal rule (`---`), or a new list bullet.
  // Safe because extractAdrRefs strips anything that isn't an ADR-NNN
  // token, so over-capture into a plain-text continuation is harmless.
  const REL = (label) => new RegExp(
    `^[-*+]?\\s*\\*\\*${label}(?:\\s*\\([^)]*\\))?:?\\*\\*:?\\s*(.+(?:\\n(?!\\s*(?:\\*\\*[A-Za-z]|##|---|[-*+]\\s|\\d+\\.\\s))[^\\n]+)*)`,
    'mi',
  );
  const supersedes = REL('Supersedes').exec(text);
  if (supersedes) for (const ref of extractAdrRefs(supersedes[1])) out.push({ from: ref, to: selfId, relation: 'supersedes' });
  const amended = REL('(?:Amended[ -]by|Amends)').exec(text);
  if (amended) for (const ref of extractAdrRefs(amended[1])) out.push({ from: selfId, to: ref, relation: 'amends' });
  const related = REL('Related').exec(text);
  if (related) for (const ref of extractAdrRefs(related[1])) out.push({ from: selfId, to: ref, relation: 'related' });
  const dependsOn = REL('Depends[ -]on').exec(text);
  if (dependsOn) for (const ref of extractAdrRefs(dependsOn[1])) out.push({ from: selfId, to: ref, relation: 'depends-on' });
  return out;
}

export function extractAdrRefs(s) {
  const refs = new Set();
  // Strip GitHub issue / commit references first to prevent false positives.
  const cleaned = s
    .replace(/#\d+/g, '')               // #1697
    .replace(/issue[s]?\s*\d+/gi, '')    // issue 1697
    .replace(/PR\s*\d+/gi, '')           // PR 1234
    .replace(/commit\s*[`a-f0-9]+/gi, '') // commit `abc123`
    .replace(/`[^`]*`/g, '');             // any backtick-quoted span
  const re = /\bADR-?(\d+)\b/gi;
  let m;
  // #2474 Bug 4: route every ADR ref through the same normalizer parseId
  // uses, so a Supersedes: ADR-0001 line lands on the same node key as
  // the file ADR-0001.md (was: padStart-then-strip produced ADR-001).
  while ((m = re.exec(cleaned))) refs.add(normalizeAdrId(m[1]));
  return [...refs];
}

#!/usr/bin/env node
// ADR index reconciler for the ruflo-adr plugin (#2666).
//
// import.mjs is convergence-only: it upserts what's on disk into
// `adr-patterns`/`adr-edges`, but has no way to remove a row whose source
// ADR file was deleted (or an edge line that was deleted from a surviving
// file) — that row survives every future import, and adr-verify.mjs
// certifies the resulting graph as "healthy" because an orphan row has no
// dangling ref and forms no cycle. See issue #2666 for the full analysis.
//
// This is reaping, not convergence, and the only reliable way to reap is a
// full drop-and-rebuild of BOTH namespaces:
//   1. Hard-purge `adr-patterns` and `adr-edges` (via the new
//      `memory purge --namespace <ns> --force` CLI command, #2666 — a real
//      DELETE, not `memory delete`'s soft tombstone that still trips the
//      UNIQUE(namespace, key) constraint on re-store, #2652).
//   2. Re-scan every ADR currently on disk and store fresh.
//   3. Re-list the namespace and assert the count equals the number of ADR
//      files scanned — a `storedRecords != 0` tally (what import.mjs prints)
//      cannot see this failure mode: if step 1 got silently clobbered by a
//      concurrent writer resurrecting old rows (#2621), step 2's upserts
//      still report "ok", and only a fresh re-count catches the drift.
//
// Normal adr-index runs explicitly upsert changed records and deterministic
// relationship keys (#2660). Reindex remains necessary for deletion/reaping:
// an upsert cannot remove a record whose source file or relationship vanished.
//
// Usage:
//   node scripts/reindex.mjs                         # purge + rebuild, markdown summary
//   REINDEX_FORMAT=json node scripts/reindex.mjs      # JSON summary
//   REINDEX_DRY_RUN=1 node scripts/reindex.mjs        # report only, no purge/store
//   ADR_ROOT=/path/to/repo node scripts/reindex.mjs   # override scan + db root (default: cwd)
//
// #2621 caveat: the purge step is lock-protected against a second concurrent
// purge/delete on the same memory.db, but NOT against every possible
// concurrent writer (a daemon or MCP server mid a sql.js-fallback
// read-modify-write cycle can still flush an older image afterward and
// resurrect what this just purged) — that requires every memory.db writer
// to respect the same lock, which is a larger change than this reconcile
// primitive. Re-run this script if that ever happens; the post-condition
// check below will tell you.

import { spawnSync } from 'node:child_process';
import { findAdrs, parseAdr } from './lib/parse-adrs.mjs';
import {
  CLI_PKG,
  adrRecordKey,
  adrRecordValue,
  edgeKey,
  edgeValue,
  memoryStoreArgs,
  uniqueEdges,
} from './lib/index-records.mjs';

// #2781: unify on the default CLI so the reindex writer and the default
// `ruflo memory search` reader hit the same store. See import.mjs for the
// full rationale.
if (process.env.CLI_CORE === '1') {
  console.warn(
    '[ruflo-adr] warning: CLI_CORE=1 is ignored — writing to the default ' +
    "`@claude-flow/cli@latest` store so `ruflo memory search` can find the records (#2781).",
  );
}

const ROOT = process.env.ADR_ROOT || process.cwd();
const dryRun = process.env.REINDEX_DRY_RUN === '1';
const fmt = process.env.REINDEX_FORMAT || 'markdown';

const NAMESPACES = ['adr-patterns', 'adr-edges'];

function purgeNamespace(namespace) {
  const r = spawnSync('npx', [
    CLI_PKG, 'memory', 'purge',
    `--namespace=${namespace}`,
    '--force',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', cwd: ROOT });
  if (r.status !== 0) {
    return { success: false, error: (r.stderr || r.stdout || '').slice(0, 300) };
  }
  return { success: true };
}

function memoryStore(namespace, key, value) {
  // Same argv-encoding note as import.mjs: `--flag=value` avoids npm's
  // non-ASCII-leading-dash argv rejection on em-dash titles (#2474 Bug 1).
  const r = spawnSync(
    'npx',
    memoryStoreArgs(namespace, key, value),
    { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', cwd: ROOT },
  );
  if (r.status !== 0) return 'error: ' + (r.stderr || r.stdout || '').slice(0, 100);
  return 'ok';
}

function memoryListCount(namespace) {
  const r = spawnSync('npx', [
    CLI_PKG, 'memory', 'list',
    '--namespace', namespace, '--format', 'json',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', cwd: ROOT });
  if (r.status !== 0) return null;
  const m = /\[[\s\S]*\]/.exec(r.stdout || '');
  if (!m) return null;
  try { return JSON.parse(m[0]).length; } catch { return null; }
}

const files = findAdrs(ROOT);
const adrs = files.map((f) => parseAdr(f, ROOT));
const byId = new Map();
const parsedEdges = [];
for (const a of adrs) {
  byId.set(a.id, a);
  parsedEdges.push(...a.links);
}
const allEdges = uniqueEdges(parsedEdges);

const result = {
  scannedRoot: ROOT,
  total: adrs.length,
  edges: allEdges.length,
  dryRun,
  purge: {},
  storedRecords: 0,
  storedEdges: 0,
  errors: [],
  postCondition: null,
};

if (dryRun) {
  if (fmt === 'json') {
    console.log(JSON.stringify(result, null, 2));
    process.exit(0);
  }
  console.log('## ADR Reindex (dry run — nothing purged or written)');
  console.log('');
  console.log(`Would purge + rebuild \`adr-patterns\` and \`adr-edges\` from ${result.total} ADR file(s) under ${ROOT}.`);
  process.exit(0);
}

// Step 1: hard-purge both namespaces (drop).
for (const ns of NAMESPACES) {
  result.purge[ns] = purgeNamespace(ns);
  if (!result.purge[ns].success) {
    result.errors.push(`purge ${ns}: ${result.purge[ns].error}`);
  }
}

// Step 2: rebuild from the current on-disk scan.
for (const a of adrs) {
  const r = memoryStore('adr-patterns', adrRecordKey(a), adrRecordValue(a));
  if (r === 'ok') result.storedRecords++;
  else result.errors.push(`${a.id} ${a.file}: ${r}`);
}
for (const e of allEdges) {
  const r = memoryStore('adr-edges', edgeKey(e), edgeValue(e));
  if (r === 'ok') result.storedEdges++;
  else result.errors.push(`${edgeKey(e)}: ${r}`);
}

// Step 3: post-condition — re-count from a fresh `memory list`, not the
// store-loop's own "ok" tally. This is the check the issue's point 3 calls
// for: a tally of successful store calls cannot see a concurrent-writer
// clobber of the purge; a fresh recount can.
const recount = memoryListCount('adr-patterns');
result.postCondition = {
  expected: adrs.length,
  actual: recount,
  ok: recount === adrs.length,
};
if (!result.postCondition.ok) {
  result.errors.push(
    `post-condition failed: expected ${adrs.length} adr-patterns record(s) after reindex, found ${recount === null ? 'unreadable' : recount}. ` +
    `Likely cause: a concurrent memory.db writer (daemon/MCP server) raced the purge (#2621). Re-run reindex.mjs.`
  );
}

if (fmt === 'json') {
  console.log(JSON.stringify(result, null, 2));
} else {
  console.log('## ADR Reindex Summary');
  console.log('');
  console.log(`Scanned root: ${ROOT}`);
  console.log(`ADR files on disk: **${result.total}**`);
  console.log('');
  console.log('### Purge');
  for (const ns of NAMESPACES) {
    console.log(`- ${ns}: ${result.purge[ns].success ? 'purged' : `FAILED — ${result.purge[ns].error}`}`);
  }
  console.log('');
  console.log('### Rebuild');
  console.log(`- Records stored to \`adr-patterns\`: ${result.storedRecords}/${result.total}`);
  console.log(`- Edges stored to \`adr-edges\`: ${result.storedEdges}/${result.edges}`);
  console.log('');
  console.log('### Post-condition (records == ADR files on disk)');
  console.log(`- Expected: ${result.postCondition.expected}, Actual: ${result.postCondition.actual}, ${result.postCondition.ok ? 'OK' : 'FAILED'}`);
  if (result.errors.length) {
    console.log('');
    console.log('### Errors');
    for (const e of result.errors.slice(0, 10)) console.log(`- ${e}`);
  }
}

process.exit(result.postCondition.ok && result.errors.length === 0 ? 0 : 1);

#!/usr/bin/env node
// adr-verify — read the persisted adr-patterns + adr-edges namespaces, surface
// dangling refs, supersede cycles, and status mismatches.
//
// Companion to scripts/import.mjs. Run after import to validate graph integrity.
// Useful in CI: exits with code 1 on supersede cycles by default, or on ANY
// issue (dangling refs, status mismatches) when VERIFY_STRICT=1 is set.
//
// Usage:
//   node scripts/verify.mjs                     # markdown report
//   VERIFY_FORMAT=json node scripts/verify.mjs  # JSON for chaining
//   VERIFY_STRICT=1 node scripts/verify.mjs     # exit 1 on ANY issue (default: only on cycles)
//   ADR_ROOT=/path/to/repo node scripts/verify.mjs   # same root import.mjs was run with

import { spawnSync } from 'node:child_process';
import { parseEdgeKey } from './lib/index-records.mjs';

// ADR-100 / #1748 Issue 3 — CLI_CORE=1 routes to lite cli-core (~2s cold-cache).
// verify only does list+retrieve across adr-patterns and adr-edges namespaces;
// no semantic search needed. JSON backend is sufficient.
const CLI_PKG = process.env.CLI_CORE === '1'
  ? '@claude-flow/cli-core@alpha'
  : '@claude-flow/cli@latest';

// #2666 point 2: must match whatever ADR_ROOT import.mjs/reindex.mjs were
// run with — the CLI resolves `.swarm/memory.db` relative to this
// subprocess's cwd, so a mismatched root silently reads the wrong db.
const ROOT = process.env.ADR_ROOT || process.cwd();

function memoryListJson(namespace) {
  const r = spawnSync('npx', [
    CLI_PKG, 'memory', 'list',
    '--namespace', namespace, '--format', 'json',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', cwd: ROOT });
  if (r.status !== 0) return [];
  const m = /\[[\s\S]*\]/.exec(r.stdout || '');
  if (!m) return [];
  try { return JSON.parse(m[0]); } catch { return []; }
}
function memoryRetrieve(namespace, key) {
  const r = spawnSync('npx', [
    CLI_PKG, 'memory', 'retrieve',
    '--namespace', namespace, '--key', key,
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', cwd: ROOT });
  if (r.status !== 0) return null;
  // Strip ANSI / box-drawing
  const txt = (r.stdout || '').replace(/\x1b\[[0-9;]*m/g, '');
  return txt;
}

const patternEntries = memoryListJson('adr-patterns');
const edgeEntries = memoryListJson('adr-edges');

const adrIds = new Set(
  patternEntries.map((e) => (e.key || '').split('::')[0]).filter(Boolean)
);

// Parse edge values to recover {from, to, relation}
const edges = [];
for (const e of edgeEntries) {
  const k = e.key || '';
  // Current deterministic key: relation:FROM->TO. Keep reading the legacy
  // relation:FROM->TO:timestamp-rand shape for seamless upgrades (#2660).
  const parsed = parseEdgeKey(k);
  if (parsed) edges.push(parsed);
}

const danglingRefs = edges.filter((e) => !adrIds.has(e.to));
const danglingFroms = edges.filter((e) => !adrIds.has(e.from));

// Cycle detection on supersedes (cycle = data corruption — ADR can't supersede itself transitively)
const supersedesGraph = new Map();
for (const e of edges.filter((e) => e.relation === 'supersedes')) {
  if (!supersedesGraph.has(e.from)) supersedesGraph.set(e.from, []);
  supersedesGraph.get(e.from).push(e.to);
}
const cycles = [];
function findCycle(node, visited, stack) {
  if (stack.has(node)) {
    cycles.push([...stack, node].join(' → '));
    return;
  }
  if (visited.has(node)) return;
  visited.add(node);
  stack.add(node);
  for (const next of supersedesGraph.get(node) || []) {
    findCycle(next, visited, stack);
  }
  stack.delete(node);
}
for (const n of supersedesGraph.keys()) findCycle(n, new Set(), new Set());

const result = {
  adrCount: adrIds.size,
  edgeCount: edges.length,
  byRelation: edges.reduce((acc, e) => { acc[e.relation] = (acc[e.relation] || 0) + 1; return acc; }, {}),
  danglingRefs,
  danglingFroms,
  cycles: [...new Set(cycles)],
};

if (process.env.VERIFY_FORMAT === 'json') {
  console.log(JSON.stringify(result, null, 2));
} else {
  console.log('## ADR Graph Verification');
  console.log('');
  console.log(`| Metric | Value |`);
  console.log(`|---|---:|`);
  console.log(`| ADRs in adr-patterns | ${result.adrCount} |`);
  console.log(`| Edges in adr-edges | ${result.edgeCount} |`);
  for (const [k, n] of Object.entries(result.byRelation).sort((a, b) => b[1] - a[1])) {
    console.log(`| edges (${k}) | ${n} |`);
  }
  console.log(`| Dangling 'to' refs | ${result.danglingRefs.length} |`);
  console.log(`| Dangling 'from' refs | ${result.danglingFroms.length} |`);
  console.log(`| Supersede cycles | ${result.cycles.length} |`);
  if (result.danglingRefs.length) {
    console.log('\n### Sample dangling refs');
    for (const d of result.danglingRefs.slice(0, 8)) console.log(`- ${d.relation} ${d.from} → ${d.to} (missing)`);
  }
  if (result.cycles.length) {
    console.log('\n### Cycles (DATA CORRUPTION — fix immediately)');
    for (const c of result.cycles) console.log(`- ${c}`);
  }
}

const strict = process.env.VERIFY_STRICT === '1';
if (result.cycles.length || (strict && (result.danglingRefs.length || result.danglingFroms.length))) {
  process.exit(1);
}
